PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kg: <https://moosedev.dev/kg/>
SELECT ?req ?title ?desc WHERE {
  VALUES ?decision { <https://moosedev.dev/kg/ArchitecturalDecision/d464cd3b-febd-44e7-984f-10997e2ae1a2> }
  ?decision <https://moosedev.dev/kg/isMotivatedBy> ?req .
  ?req a <https://moosedev.dev/kg/Requirement> ; rdfs:label ?title ; <https://moosedev.dev/kg/hasDescription> ?desc .
}
ORDER BY ?title

